from pathlib import Path
import sys

candidate = Path('candidate')
assert {p.name for p in candidate.iterdir()} == {'feature.patch', 'security.patch'}
allowed = {'app/service.py', 'app/operations.py'}
for name in ('feature.patch', 'security.patch'):
    patch = (candidate / name).read_text(encoding='utf-8')
    assert patch and patch.endswith('\\n')
    assert '\\x00' not in patch
    for line in patch.splitlines():
        if line.startswith(('--- ', '+++ ')):
            assert line[4:6] in ('a/', 'b/')
            assert line[6:] in allowed
    print(f'{name}: UTF-8 diff, allowed existing paths only')
for version in ('U', 'R'):
    expected = Path('.scratch') / version
    applied = Path('.scratch') / f'applied-{version}'
    expected_paths = {p.relative_to(expected) for p in expected.rglob('*') if p.is_file()}
    applied_paths = {p.relative_to(applied) for p in applied.rglob('*') if p.is_file()}
    assert expected_paths == applied_paths
    for relative in expected_paths:
        assert (expected / relative).read_bytes() == (applied / relative).read_bytes()
    for relative in ('app/runtime.py', 'app/__init__.py'):
        assert (applied / relative).read_bytes() == (Path('inputs/B') / relative).read_bytes()
    print(f'Applied {version}: identical to validated scratch implementation')
print(f'Python: {sys.version}')
